/** Contracts for the first durable general-agent task.
 *
 * This module is intentionally runtime-neutral: Absurd is a Postgres-backed
 * durable task runner and Pi owns the model/session loop. It does not provide
 * a SQLite implementation or hide either dependency behind `any`.
 */

export const GENERAL_AGENT_TASK = "pi-swarm.general-agent" as const;
export const GENERAL_AGENT_TOOLS = ["general_agent_status", "general_agent_cancel"] as const;
export type GeneralAgentToolName = typeof GENERAL_AGENT_TOOLS[number];

export type GeneralAgentInput = {
  prompt: string;
  workspace: string;
  sessionId: string;
  conversationId: string;
  provider: string;
  model: string;
  maxTurns?: number;
  timeoutSeconds?: number;
};

export type GeneralAgentOutput = {
  status: "completed" | "failed" | "cancelled";
  sessionId: string;
  conversationId: string;
  assistantMessageCount: number;
  lastMessageId?: string;
  errorCode?: "aborted" | "timeout" | "provider" | "tool" | "checkpoint" | "unknown";
};

export type GeneralAgentCheckpoint =
  | { kind: "message_end"; messageId: string; role: "user" | "assistant" | "toolResult"; sequence: number }
  | { kind: "turn_end"; sequence: number }
  | { kind: "agent_end"; sequence: number };

export interface GeneralAgentRuntime {
  readonly sessionId: string;
  readonly conversationId: string;
  run(prompt: string, signal: AbortSignal): Promise<void>;
  continue(signal: AbortSignal): Promise<void>;
  checkpoint(checkpoint: GeneralAgentCheckpoint): Promise<void>;
}

export type GeneralAgentStatusResult = {
  taskId: string;
  state: "pending" | "running" | "completed" | "failed" | "cancelled";
  attempt: number;
  output?: GeneralAgentOutput;
};

export type GeneralAgentToolRequest =
  | { tool: "general_agent_status"; taskId: string }
  | { tool: "general_agent_cancel"; taskId: string };

export type GeneralAgentToolResponse =
  | { ok: true; tool: "general_agent_status"; status: GeneralAgentStatusResult }
  | { ok: true; tool: "general_agent_cancel"; cancelled: boolean }
  | { ok: false; tool: GeneralAgentToolName; error: "invalid_request" | "not_found" | "denied" };

export function validateGeneralAgentInput(input: unknown): GeneralAgentInput {
  if (!isRecord(input) || !nonEmpty(input.prompt) || !nonEmpty(input.workspace) ||
      !nonEmpty(input.sessionId) || !nonEmpty(input.conversationId) ||
      !nonEmpty(input.provider) || !nonEmpty(input.model)) {
    throw new Error("invalid general-agent input: required strings are missing");
  }
  if (input.maxTurns !== undefined && (!safePositiveInt(input.maxTurns) || input.maxTurns > 1000)) {
    throw new Error("invalid general-agent input: maxTurns");
  }
  if (input.timeoutSeconds !== undefined && (!safePositiveInt(input.timeoutSeconds) || input.timeoutSeconds > 86400)) {
    throw new Error("invalid general-agent input: timeoutSeconds");
  }
  return { prompt: input.prompt, workspace: input.workspace, sessionId: input.sessionId,
    conversationId: input.conversationId, provider: input.provider, model: input.model,
    ...(input.maxTurns === undefined ? {} : { maxTurns: input.maxTurns }),
    ...(input.timeoutSeconds === undefined ? {} : { timeoutSeconds: input.timeoutSeconds }) };
}

function isRecord(value: unknown): value is Record<string, any> { return !!value && typeof value === "object" && !Array.isArray(value); }
function nonEmpty(value: unknown): value is string { return typeof value === "string" && value.trim().length > 0; }
function safePositiveInt(value: unknown): value is number { return typeof value === "number" && Number.isSafeInteger(value) && value > 0; }

import { Absurd, type TaskContext } from "absurd-sdk";
import {
  GENERAL_AGENT_TASK,
  validateGeneralAgentInput,
  type GeneralAgentInput,
  type GeneralAgentOutput,
  type GeneralAgentRuntime,
} from "../../runtime-contracts/dist/general-agent.js";

/** Runtime construction is deliberately injected: production can construct a Pi
 * Agent/Session, while tests can record calls without a provider or Postgres. */
export type GeneralAgentRuntimeFactory = (input: GeneralAgentInput, ctx: TaskContext, checkpoint: GeneralAgentRuntime["checkpoint"]) => Promise<GeneralAgentRuntime> | GeneralAgentRuntime;

export function createGeneralAgentHandler(createRuntime: GeneralAgentRuntimeFactory) {
  return async (raw: GeneralAgentInput, ctx: TaskContext): Promise<GeneralAgentOutput> => {
      const input = validateGeneralAgentInput(raw);
      let sequence = 0;
      // Pi's session subscriber calls this only after message_end. Absurd's
      // step makes that boundary idempotent across worker retries.
      const checkpoint = async (value: Parameters<GeneralAgentRuntime["checkpoint"]>[0]) => {
        const n = ++sequence;
        await ctx.step(`pi.${value.kind}.${n}`, async () => ({ kind: value.kind, sequence: n, messageId: "messageId" in value ? value.messageId : undefined }));
      };
      const runtime = await createRuntime(input, ctx, checkpoint);
      try {
        if (hasResumableContext(runtime)) await runtime.continue(signalFor(ctx, input));
        else await runtime.run(input.prompt, signalFor(ctx, input));
        return { status: "completed", sessionId: input.sessionId, conversationId: input.conversationId, assistantMessageCount: sequence };
      } catch (error) {
        const aborted = error instanceof Error && (error.name === "AbortError" || error.message === "aborted");
        return { status: aborted ? "cancelled" : "failed", sessionId: input.sessionId, conversationId: input.conversationId, assistantMessageCount: sequence, errorCode: aborted ? "aborted" : "provider" };
      }
  };
}

export function registerGeneralAgentTask(absurd: Absurd, createRuntime: GeneralAgentRuntimeFactory): void {
  absurd.registerTask<GeneralAgentInput, GeneralAgentOutput>({ name: GENERAL_AGENT_TASK }, createGeneralAgentHandler(createRuntime));
}

/** Factories may expose this without adding it to the narrow runtime contract. */
function hasResumableContext(runtime: GeneralAgentRuntime): boolean {
  return (runtime as GeneralAgentRuntime & { resumable?: boolean }).resumable === true;
}

function signalFor(_ctx: TaskContext, input: GeneralAgentInput): AbortSignal {
  const controller = new AbortController();
  if (input.timeoutSeconds) setTimeout(() => controller.abort(), input.timeoutSeconds * 1000).unref?.();
  return controller.signal;
}

export type PiContinuationApi = {
  runAgentLoopContinue: (...args: never[]) => Promise<unknown>;
};

export function assertPiContinuationApi(api: Partial<PiContinuationApi>): void {
  if (typeof api.runAgentLoopContinue !== "function") throw new Error("Pi runAgentLoopContinue API is required");
}

