import { createId, ID, JsonObject, newId } from "./contracts.js";

export type AgentKind = "pi-session" | "pi-headless" | "external";
export type AgentLifecycle = "starting" | "idle" | "running" | "waiting" | "stopped" | "failed";
export type JobState = "queued" | "leased" | "running" | "succeeded" | "failed" | "cancelled";

export interface AgentBinding {
  readonly id: ID; readonly kind: AgentKind; readonly workspace: string;
  readonly conversationId?: string; readonly capabilityProfile?: ID;
  readonly status: AgentLifecycle; readonly lastHeartbeatAt?: string;
  readonly revision: number; readonly createdAt: string; readonly updatedAt: string;
}
export interface AgentRegistration { readonly id?: ID; readonly kind: AgentKind; readonly workspace: string; readonly conversationId?: string; readonly capabilityProfile?: ID; }
export interface JobTarget { readonly agentId?: ID; readonly profileId?: ID; readonly workflowId?: ID; }
export interface JobRequest { readonly prompt: string; readonly target: JobTarget; }
export interface Job {
  readonly id: ID; readonly request: JobRequest; readonly policyProfile?: ID;
  readonly state: JobState; readonly attempt: number; readonly idempotencyKey: string;
  readonly createdAt: string; readonly updatedAt: string;
}
export interface CreateJobRequest { readonly request: JobRequest; readonly policyProfile?: ID; readonly idempotencyKey: string; }

export type ControlPlaneEventType = "agent.registered" | "agent.heartbeat" | "agent.stopped" | "job.created" | "job.cancelled" | "job.retried";
export interface ControlPlaneEvent { readonly id: ID; readonly sequence: number; readonly type: ControlPlaneEventType; readonly entityId: ID; readonly occurredAt: string; readonly correlationId?: ID; readonly actor: string; readonly data?: JsonObject; readonly redacted: true; }
export interface EventSubscription { readonly events: readonly ControlPlaneEvent[]; readonly nextSequence: number; }

export type ControlPlaneErrorCode = "invalid_request" | "not_found" | "conflict" | "already_terminal";
export class ControlPlaneError extends Error {
  constructor(readonly code: ControlPlaneErrorCode, message: string) { super(message); this.name = "ControlPlaneError"; }
}

/** Transport-neutral control-plane boundary. Implementations own state and event ordering. */
export interface ControlPlane {
  registerAgent(request: AgentRegistration, actor: string): Promise<AgentBinding>;
  heartbeatAgent(id: ID, actor: string, at?: string): Promise<AgentBinding>;
  stopAgent(id: ID, actor: string): Promise<AgentBinding>;
  createJob(request: CreateJobRequest, actor: string): Promise<Job>;
  getJob(id: ID): Promise<Job>;
  cancelJob(id: ID, actor: string): Promise<Job>;
  retryJob(id: ID, actor: string): Promise<Job>;
  readEvents(afterSequence?: number, limit?: number): Promise<EventSubscription>;
}

const copy = <T>(value: T): T => structuredClone(value);
const now = (): string => new Date().toISOString();

/** Deterministic, process-local fake for contract tests and adapter development. */
export class InProcessControlPlane implements ControlPlane {
  private readonly agents = new Map<ID, AgentBinding>();
  private readonly jobs = new Map<ID, Job>();
  private readonly idempotency = new Map<string, ID>();
  private readonly events: ControlPlaneEvent[] = [];
  private sequence = 0;

  async registerAgent(request: AgentRegistration, actor: string): Promise<AgentBinding> {
    if (!request.workspace.trim()) throw new ControlPlaneError("invalid_request", "workspace is required");
    const timestamp = now();
    const agent: AgentBinding = { id: request.id ?? newId("agent"), kind: request.kind, workspace: request.workspace, conversationId: request.conversationId, capabilityProfile: request.capabilityProfile, status: "starting", revision: 1, createdAt: timestamp, updatedAt: timestamp };
    if (this.agents.has(agent.id)) throw new ControlPlaneError("conflict", `agent ${agent.id} already exists`);
    this.agents.set(agent.id, agent); this.emit("agent.registered", agent.id, actor); return copy(agent);
  }
  async heartbeatAgent(id: ID, actor: string, at = now()): Promise<AgentBinding> {
    const current = this.agent(id); const next: AgentBinding = { ...current, status: current.status === "starting" ? "idle" : current.status, lastHeartbeatAt: at, revision: current.revision + 1, updatedAt: now() };
    this.agents.set(id, next); this.emit("agent.heartbeat", id, actor); return copy(next);
  }
  async stopAgent(id: ID, actor: string): Promise<AgentBinding> { const current = this.agent(id); const next = { ...current, status: "stopped" as const, revision: current.revision + 1, updatedAt: now() }; this.agents.set(id, next); this.emit("agent.stopped", id, actor); return copy(next); }
  async createJob(request: CreateJobRequest, actor: string): Promise<Job> {
    if (!request.request.prompt.trim() || !request.idempotencyKey.trim()) throw new ControlPlaneError("invalid_request", "prompt and idempotencyKey are required");
    const existing = this.idempotency.get(request.idempotencyKey); if (existing) return this.getJob(existing);
    const timestamp = now(); const job: Job = { id: newId("job"), request: copy(request.request), policyProfile: request.policyProfile, state: "queued", attempt: 0, idempotencyKey: request.idempotencyKey, createdAt: timestamp, updatedAt: timestamp };
    this.jobs.set(job.id, job); this.idempotency.set(job.idempotencyKey, job.id); this.emit("job.created", job.id, actor); return copy(job);
  }
  async getJob(id: ID): Promise<Job> { const job = this.jobs.get(id); if (!job) throw new ControlPlaneError("not_found", `job ${id} not found`); return copy(job); }
  async cancelJob(id: ID, actor: string): Promise<Job> { const job = await this.getJob(id); if (["succeeded", "failed", "cancelled"].includes(job.state)) throw new ControlPlaneError("already_terminal", `job ${id} is terminal`); const next = { ...job, state: "cancelled" as const, updatedAt: now() }; this.jobs.set(id, next); this.emit("job.cancelled", id, actor); return copy(next); }
  async retryJob(id: ID, actor: string): Promise<Job> { const job = await this.getJob(id); if (!["failed", "cancelled"].includes(job.state)) throw new ControlPlaneError("conflict", `job ${id} is not retryable`); const next = { ...job, state: "queued" as const, attempt: job.attempt + 1, updatedAt: now() }; this.jobs.set(id, next); this.emit("job.retried", id, actor); return copy(next); }
  async readEvents(afterSequence = 0, limit = 100): Promise<EventSubscription> { if (!Number.isSafeInteger(afterSequence) || afterSequence < 0 || !Number.isSafeInteger(limit) || limit < 1) throw new ControlPlaneError("invalid_request", "invalid event cursor or limit"); const events = this.events.filter(event => event.sequence > afterSequence).slice(0, limit); return { events: copy(events), nextSequence: events.at(-1)?.sequence ?? afterSequence }; }
  private agent(id: ID): AgentBinding { const agent = this.agents.get(id); if (!agent) throw new ControlPlaneError("not_found", `agent ${id} not found`); return agent; }
  private emit(type: ControlPlaneEventType, entityId: ID, actor: string): void { this.events.push({ id: newId("event"), sequence: ++this.sequence, type, entityId, occurredAt: now(), actor, redacted: true }); }
}

import { resolve } from "node:path";
import { Policy } from "../../policy/src/index.ts";
import { AgentManager, createPiRunner, registerAgents } from "../../agents/src/index.ts";
import { MCPManager } from "../../mcp/src/index.ts";
import { registerSwarmPrompt } from "./swarm-prompt.ts";

type RuntimeState = { initialized: boolean; cwd: string; agents?: AgentManager; policy?: Policy; mcp?: MCPManager; };
const runtimeByPi = new WeakMap<object, RuntimeState>();

type Pi = any;

/** Single integration boundary for the Pi-Swarm extensions. */
export function registerSwarmRuntime(pi: Pi, options: { cwd?: string; closed?: boolean; allowedTools?: string[]; allowedSkills?: string[]; allowMutation?: boolean; allowNetwork?: boolean } = {}): RuntimeState {
  const cwd = resolve(options.cwd ?? pi.getCwd?.() ?? process.cwd());
  const existing = runtimeByPi.get(pi as object);
  if (existing?.initialized && existing.cwd === cwd) return existing;
  const state: RuntimeState = { initialized: true, cwd };
  runtimeByPi.set(pi as object, state);

  // Establish prompt and resource policy before feature registration.
  registerSwarmPrompt(pi);
  state.policy = new Policy({ workspace: cwd, allowedTools: options.allowedTools, allowMutation: options.allowMutation, allowNetwork: options.allowNetwork });

  // Dedicated extensions own tool registration; the umbrella only owns shared
  // policy/identity and must never register duplicate tools.

  state.agents = registerAgents(pi, new AgentManager({ cwd, concurrency: 4, runner: createPiRunner(pi) }), pi.getSessionId?.() ?? pi.sessionId);
  pi.on?.("session_shutdown", () => state.mcp?.close());
  const manifests = pi.mcpManifests ?? [];
  if (Array.isArray(manifests)) state.mcp = new MCPManager(manifests, { closed: options.closed ?? true, registerTool: tool => pi.registerTool(tool) });
  pi.registerCommand?.("swarm-runtime", { description: "Inspect integrated Pi-Swarm runtime", handler: async (_args: string, ctx: any) => ctx.ui?.notify?.(`Pi-Swarm runtime active at ${cwd}; mcp=${manifests.length}`, "info") });
  return state;
}

export default function swarmRuntimeExtension(pi: Pi) { return registerSwarmRuntime(pi); }

import { describe, expect, it } from "vitest";
import { createGeneralAgentHandler } from "../src/general-agent-adapter.js";

const input = { prompt: "hello", workspace: "/tmp", sessionId: "s", conversationId: "c", provider: "test", model: "test" };
const ctx = { step: async (_name: string, fn: () => Promise<unknown>) => fn() } as any;

describe("general-agent adapter", () => {
  it("checkpoints through Absurd steps and runs injected runtime", async () => {
    const calls: string[] = [];
    const result = await createGeneralAgentHandler((_input, _ctx, checkpoint) => ({
      sessionId: "s", conversationId: "c", resumable: false,
      run: async (_p, _s) => { calls.push("run"); }, continue: async () => { calls.push("continue"); },
    } as any))(input, ctx);
    expect(result.status).toBe("completed");
    expect(calls).toEqual(["run"]);
  });

  it("uses continuation only when runtime marks a resumable boundary", async () => {
    const calls: string[] = [];
    await createGeneralAgentHandler((_input, _ctx, checkpoint) => ({
      sessionId: "s", conversationId: "c", resumable: true,
      run: async () => calls.push("run"), continue: async () => calls.push("continue"),
    } as any))(input, ctx);
    expect(calls).toEqual(["continue"]);
  });
});

import { createHash } from "node:crypto";
export * from "./general-agent-adapter.js";
import { mkdir } from "node:fs/promises";
import { execFile } from "node:child_process";
import { promisify } from "node:util";

const execFileAsync = promisify(execFile);
export type AgentStatus = "queued" | "running" | "completed" | "failed" | "cancelled";
export interface Profile { name: string; systemPrompt?: string; capabilities?: string[]; tools?: string[]; }
export interface Preset extends Profile { provider?: string; model?: string; concurrency?: number; worktree?: boolean; }
export interface AgentSpec { id?: string; parentId?: string; parentSessionId?: string; sessionId?: string; task: string; provider?: string; model?: string; profile?: string; preset?: string; capabilities?: string[]; worktree?: string | boolean; background?: boolean; }
export interface AgentResult { id: string; status: AgentStatus; output?: string; error?: string; startedAt?: string; completedAt: string; durationMs: number; }
export interface BackgroundHandle { readonly id: string; readonly parentId?: string; readonly sessionId: string; wait(timeoutMs?: number): Promise<AgentResult>; cancel(): boolean; steer(instruction: string): boolean; }
export type AgentCompletionSink = (result: AgentResult) => void | Promise<void>;
export interface AgentCompletionEvent { readonly type: "agent.completed"; readonly agentId: string; readonly parentId?: string; readonly parentSessionId?: string; readonly sessionId: string; readonly background: boolean; readonly result: AgentResult; }
export type AgentEventSink = (event: AgentCompletionEvent) => void | Promise<void>;
export interface RunnerContext { signal: AbortSignal; spec: Required<Pick<AgentSpec, "id" | "task">> & AgentSpec; task: string; profile?: Profile; provider?: string; model?: string; cwd: string; instructions: readonly string[]; steering: readonly string[]; }
export type Runner = (ctx: RunnerContext) => Promise<string>;

/** Build a real Pi child-session runner. The child is deliberately prevented
 * from recursively spawning this control surface; the parent owns orchestration. */
export function createPiRunner(pi: any): Runner {
  return async (ctx) => {
    if (typeof pi?.exec !== "function") return defaultRunner(ctx);
    const sessionDir = `${ctx.cwd}/.pi/agent-sessions`;
    await mkdir(sessionDir, { recursive: true });
    const sessionPath = `${sessionDir}/${ctx.spec.sessionId ?? ctx.spec.id}.jsonl`;
    const args = ["--mode", "text", "--print", "--session", sessionPath, "--exclude-tools", "Agent,AgentControl", "-p", ctx.task];
    if (ctx.provider) args.unshift("--provider", ctx.provider);
    if (ctx.model) args.unshift("--model", ctx.model);
    const result = await pi.exec("pi", args, { cwd: ctx.cwd, signal: ctx.signal });
    if (result?.killed || result?.code !== 0) throw new Error(`child pi failed (${result?.killed ? "killed" : `exit ${result?.code}`}): ${(result?.stderr ?? "").trim()}`);
    return String(result?.stdout ?? "").trim();
  };
}

const clone = <T>(v: T): T => structuredClone(v);
const unique = (xs: readonly string[]) => [...new Set(xs.filter(Boolean))];
const stableId = (parentId: string | undefined, sessionId: string, task: string) => `agent-${createHash("sha256").update(`${parentId ?? "root"}\n${sessionId}\n${task}`).digest("hex").slice(0, 20)}`;

export class AgentManager {
  private readonly agents = new Map<string, { spec: AgentSpec; result?: AgentResult; promise: Promise<AgentResult>; abort: AbortController; steering: string[]; listeners: Set<(r: AgentResult) => void> }>();
  private active = 0;
  private readonly queue: (() => void)[] = [];
  private readonly profiles = new Map<string, Profile>();
  private readonly presets = new Map<string, Preset>();
  private readonly eventSinks = new Set<AgentEventSink>();
  constructor(private readonly options: { runner?: Runner; cwd?: string; concurrency?: number; profiles?: Profile[]; presets?: Record<string, Preset>; onComplete?: AgentCompletionSink; eventSink?: AgentEventSink } = {}) {
    if (options.eventSink) this.eventSinks.add(options.eventSink);
    for (const p of options.profiles ?? []) this.profiles.set(p.name, clone(p));
    for (const [name, p] of Object.entries(options.presets ?? {})) this.presets.set(name, { ...clone(p), name: p.name || name });
  }
  addProfile(profile: Profile): void { this.profiles.set(profile.name, clone(profile)); }
  addEventSink(sink: AgentEventSink): () => void { this.eventSinks.add(sink); return () => this.eventSinks.delete(sink); }
  addPreset(name: string, preset: Preset): void { this.presets.set(name, { ...clone(preset), name: preset.name || name }); }
  profile(name: string): Profile | undefined { const p = this.profiles.get(name); return p && clone(p); }
  private resolve(spec: AgentSpec) {
    const parent = spec.parentId ? this.agents.get(spec.parentId) : undefined;
    const parentSpec = parent?.spec;
    const profile = spec.profile ? this.profiles.get(spec.profile) : parentSpec?.profile ? this.profiles.get(parentSpec.profile) : undefined;
    const preset = spec.preset ? this.presets.get(spec.preset) : undefined;
    const parentPreset = parentSpec?.preset ? this.presets.get(parentSpec.preset) : undefined;
    return { profile: profile ?? preset, provider: spec.provider ?? preset?.provider ?? parentSpec?.provider ?? parentPreset?.provider, model: spec.model ?? preset?.model ?? parentSpec?.model ?? parentPreset?.model, capabilities: unique([...(parentPreset?.capabilities ?? []), ...(parentPreset?.capabilities ?? []), ...(preset?.capabilities ?? []), ...(profile?.capabilities ?? []), ...(spec.capabilities ?? [])]), worktree: spec.worktree ?? preset?.worktree ?? false };
  }
  spawn(spec: AgentSpec): BackgroundHandle {
    if (!spec.task?.trim()) throw new Error("agent task is required");
    const sessionId = spec.sessionId ?? (spec.parentId ? `session:${spec.parentId}` : `session:${stableId(spec.parentId, "root", spec.task)}`);
    const id = spec.id ?? stableId(spec.parentId, sessionId, spec.task); if (this.agents.has(id)) throw new Error(`agent ${id} already exists`);
    const abort = new AbortController(); const steering: string[] = []; const listeners = new Set<(r: AgentResult) => void>();
    let resolve!: (r: AgentResult) => void; const promise = new Promise<AgentResult>(r => resolve = r);
    const entry = { spec: { ...spec, id }, abort, steering, listeners, promise, result: undefined as AgentResult | undefined }; this.agents.set(id, entry);
    const run = () => { this.active++; void this.execute(entry.spec, sessionId, entry).then(r => { entry.result = r; resolve(r); for (const l of listeners) l(clone(r)); const result = clone(r); if (this.options.onComplete) void Promise.resolve(this.options.onComplete(result)).catch(() => undefined); if (spec.background) for (const sink of this.eventSinks) void Promise.resolve(sink({ type: "agent.completed", agentId: r.id, parentId: spec.parentId, parentSessionId: spec.parentSessionId, sessionId, background: true, result })).catch(() => undefined); }).finally(() => { this.active--; this.drain(); }); };
    if (this.active < Math.max(1, this.options.concurrency ?? 4)) run(); else this.queue.push(run);
    return { id, parentId: spec.parentId, sessionId, wait: (timeoutMs?: number) => timeout(promise, timeoutMs), cancel: () => { if (entry.result) return false; abort.abort(); return true; }, steer: (instruction: string) => { if (entry.result || !instruction.trim()) return false; steering.push(instruction); return true; } };
  }
  private drain() { const limit = Math.max(1, this.options.concurrency ?? 4); while (this.active < limit && this.queue.length) this.queue.shift()!(); }
  private async execute(spec: AgentSpec, sessionId: string, entry: { abort: AbortController; steering: string[] }): Promise<AgentResult> {
    const started = Date.now(), startedAt = new Date(started).toISOString(), resolved = this.resolve(spec); let cwd = this.options.cwd ?? process.cwd();
    if (resolved.worktree) cwd = await this.createWorktree(cwd, spec.id!);
    const instructions = [...(resolved.profile?.systemPrompt ? [resolved.profile.systemPrompt] : []), ...(resolved.capabilities ?? []).map(c => `Capability: ${c}`)];
    try { const output = await (this.options.runner ?? defaultRunner)({ signal: entry.abort.signal, spec: { ...spec, id: spec.id!, sessionId }, profile: resolved.profile, provider: resolved.provider, model: resolved.model, task: spec.task, cwd, instructions, steering: entry.steering }); const result: AgentResult = { id: spec.id!, status: entry.abort.signal.aborted ? "cancelled" : "completed", output, startedAt, completedAt: new Date().toISOString(), durationMs: Date.now() - started }; return result; }
    catch (e) { return { id: spec.id!, status: entry.abort.signal.aborted ? "cancelled" : "failed", error: e instanceof Error ? e.message : String(e), startedAt, completedAt: new Date().toISOString(), durationMs: Date.now() - started }; }
